import React, { useState, useEffect } from 'react';
import {
  uploadFile,
  getFiles,
  downloadEncryptedFile,
  downloadDecryptedFile,
  deleteFile
} from '../services/api';

import CryptoFlow from '../components/CryptoFlow';
import SciFiAlert from '../components/SciFiAlert';

import {
  Upload,
  Server,
  HardDrive,
  Terminal,
  Play,
  X,
  RefreshCw,
  FileCheck,
  FileText
} from 'lucide-react';

const Dashboard = () => {

  const [files, setFiles] = useState([]);
  const [fileToUpload, setFileToUpload] = useState(null);
  const [uploadStep, setUploadStep] = useState(0);
  const [logs, setLogs] = useState([]);
  const [selectedFile, setSelectedFile] = useState(null);
  const [successMode, setSuccessMode] = useState(false);
  const [customAlert, setCustomAlert] = useState(null);
  const [cryptoMode, setCryptoMode] = useState('hybrid');

  useEffect(() => { fetchFiles(); }, []);

  const fetchFiles = async () => {
    try {
      const res = await getFiles();
      setFiles(res.data);
    } catch (e) {}
  };

  const addLog = (msg) => {
    const timestamp = new Date().toLocaleTimeString();
    setLogs(prev => [`[${timestamp}] ${msg}`, ...prev]);
  };

  const resetUpload = () => {
    setFileToUpload(null);
    setSuccessMode(false);
    setUploadStep(0);
  };

  const onFileDrop = (e) => {
    const f = e.target.files[0];
    if (f) {
      setFileToUpload(f);
      setSuccessMode(false);
    }
  };

  const startEncryption = async () => {
    if (!fileToUpload) return;

    setUploadStep(1);
    setLogs([]);
    addLog("Initializing protocol");

    setTimeout(() => setUploadStep(2), 800);
    setTimeout(() => setUploadStep(3), 1600);
    setTimeout(() => setUploadStep(4), 2400);

    try {
      const res = await uploadFile(fileToUpload, cryptoMode);
      setTimeout(() => {
        setUploadStep(5);
        setSuccessMode(true);
        addLog(`Sealed ID: ${res.data.file_id}`);
        fetchFiles();
      }, 3200);
    } catch {
      setCustomAlert({
        type: "error",
        title: "Upload Failed",
        message: "Check backend"
      });
      setUploadStep(0);
    }
  };

  const handleEncryptedDownload = async (file) => {
    await downloadEncryptedFile(file.id, file.filename);
  };

  const handleDecryptedDownload = async (file) => {
    if (file.mode !== 'hybrid') {
      setCustomAlert({ type: 'error', title: 'Denied', message: 'RSA benchmark only.' });
      return;
    }
    await downloadDecryptedFile(file.id, file.filename);
  };

  return (
    <div className="p-8 space-y-6 relative h-full flex flex-col">
      {customAlert && <SciFiAlert {...customAlert} onClose={() => setCustomAlert(null)} />}

      {/* ================= MODAL ================= */}
      {selectedFile && (
        <div className="fixed inset-0 bg-black/90 flex items-center justify-center z-50">
          <div className="bg-scifi-panel border border-neon-blue w-[600px] p-8 rounded-2xl relative">
            <button onClick={() => setSelectedFile(null)} className="absolute top-4 right-4"><X /></button>

            <h2 className="text-xl font-bold mb-4">File Controls</h2>

            <div className="flex justify-end gap-3">
              <button
                onClick={async () => {
                  await deleteFile(selectedFile.id);
                  setFiles(prev => prev.filter(f => f.id !== selectedFile.id));
                  setSelectedFile(null);
                }}
                className="px-4 py-2 border border-red-500 text-red-500 rounded"
              >
                Delete
              </button>

              <button
                onClick={() => handleEncryptedDownload(selectedFile)}
                className="px-4 py-2 border border-gray-500 rounded"
              >
                Download Encrypted
              </button>

              <button
                onClick={() => handleDecryptedDownload(selectedFile)}
                className="px-4 py-2 bg-neon-blue text-black font-bold rounded"
              >
                Decrypt & Download
              </button>
            </div>
          </div>
        </div>
      )}

      {/* ================= HEADER ================= */}
      <div className="flex justify-between items-end">
        <div>
          <h2 className="text-2xl font-bold text-white">QS-VAULT</h2>
          <p className="text-gray-400 text-xs">Post-Quantum Gateway</p>
        </div>

        <select
          value={cryptoMode}
          onChange={(e) => setCryptoMode(e.target.value)}
          className="bg-black border border-gray-700 text-xs text-neon-blue p-2 rounded"
        >
          <option value="hybrid">Hybrid (X25519 + AES)</option>
          <option value="rsa">RSA-2048 (Baseline)</option>
        </select>
      </div>

      {/* ================= MAIN ================= */}
      <div className="grid grid-cols-3 gap-6 flex-1 min-h-0">

        {/* LEFT */}
        <div className="col-span-2 flex flex-col gap-6">

          <div className="bg-scifi-panel border border-scifi-border rounded-xl p-6 min-h-[300px] flex flex-col justify-center">
            {uploadStep > 0 || successMode ? (
              <div className="text-center">
                <h3 className="text-neon-green font-bold mb-6">
                  {successMode ? "ENCRYPTION COMPLETE" : "RUNNING"}
                </h3>

                <CryptoFlow currentStep={uploadStep} mode={cryptoMode} />

                {successMode && (
                  <button
                    onClick={resetUpload}
                    className="mt-6 px-6 py-2 bg-white text-black rounded"
                  >
                    <RefreshCw className="inline mr-2" size={14} />
                    Encrypt Another
                  </button>
                )}
              </div>
            ) : !fileToUpload ? (
              <label className="border-2 border-dashed border-gray-700 rounded-lg h-full flex flex-col items-center justify-center cursor-pointer">
                <input type="file" onChange={onFileDrop} className="hidden" />
                <Upload className="mb-3" />
                Drop file
              </label>
            ) : (
              <div className="text-center">
                <FileText className="mx-auto mb-3" />
                <p>{fileToUpload.name}</p>
                <button onClick={startEncryption} className="mt-4 px-6 py-2 bg-neon-green text-black rounded">
                  <Play className="inline mr-2" size={14} />
                  Engage
                </button>
              </div>
            )}
          </div>

          {/* LOGS */}
          <div className="bg-black border border-gray-800 rounded-xl p-4 flex-1 overflow-y-auto">
            {logs.map((l, i) => <p key={i} className="text-xs font-mono">{l}</p>)}
          </div>
        </div>

        {/* RIGHT */}
        <div className="bg-scifi-panel border border-scifi-border rounded-xl p-4 flex flex-col">
          <h3 className="text-sm font-bold mb-4 flex items-center gap-2">
            <Server size={14}/> Vault Contents
          </h3>

          <div className="overflow-y-auto flex-1 space-y-2">
            {files.map(file => (
              <div
                key={file.id}
                onClick={() => setSelectedFile(file)}
                className="p-2 bg-white/5 rounded cursor-pointer"
              >
                <p className="text-xs font-bold truncate">{file.filename}</p>
                <p className="text-[10px] text-gray-500">{file.mode}</p>
              </div>
            ))}
          </div>
        </div>

      </div>
    </div>
  );
};

export default Dashboard;
